fields.InputDefinition:
{
  "goal": "Open the application switcher dropdown next to the logo (NOT the Ctrl+K search box) and go to Data Explorer, then its Data section. Open the 'Products' entity via the LEFT sidebar 'Search entities...' box (type 'Products', click the exact match) and wait for the records grid to render. Pages can take 10-30s to load in this resource-constrained environment — wait for content rather than navigating away. Then walk these sections IN ORDER, and as you arrive at each one set \"checkpointReached\" to the exact checkpoint name shown: (1) cards-view — open the view-type switcher dropdown in the view toolbar (a button showing the current type like 'Grid' with a chevron) and choose 'Cards' so the records re-render as a card grid; (2) view-selector-select — open the saved-view selector (layer-group icon labeled with the current view name or '(Default)'), confirm the Views panel lists at least a '(Default)' option, and click it to apply; (3) create-saved-view — open the saved-view selector again, click 'New View' in the panel footer, enter a unique name such as 'CU Grid Test 4821', and confirm the new view is created and becomes the active view (its name shows on the selector or under 'My Views'); (4) timeline-view — open the view-type switcher again and, if 'Timeline' is offered, select it and confirm a chronological timeline layout (if Timeline is not offered, selecting another type such as Cards and seeing the view re-render is acceptable); (5) view-open-in-tab — make sure the saved view you created in step 3 is the active view (its name shows on the saved-view selector; pick it from the selector if not), then click the 'Open this view in a new tab' icon button (external-link icon) directly to the RIGHT of the saved-view selector — it only appears while a saved view is selected, never for '(Default)', and is not inside the Views panel — and confirm the view opens as its own workspace tab showing the entity's records; (6) reset-view — make a change that marks the view modified (click a column header to sort, or type into the 'Filter records...' box), then open the saved-view selector and click 'Reset to Default', confirming the view reverts and the modified indicator clears. Keep going until every section has been visited.",
  "startUrl": "http://localhost:4200",
  "allowedDomains": [
    "localhost",
    "*.auth0.com"
  ],
  "auth": {
    "bindings": [
      {
        "domains": [
          "localhost",
          "*.auth0.com"
        ],
        "method": {
          "Type": "Basic",
          "Username": "{{authUsername}}",
          "Password": "{{authPassword}}",
          "Strategy": "FormLogin"
        }
      }
    ]
  }
}

fields.ExpectedOutcomes:
{
  "goalCompleted": true,
  "finalUrlPattern": "^http://localhost:4200",
  "minConfidence": 0.7,
  "maxSteps": 90,
  "checkpoints": [
    {
      "name": "cards-view",
      "instruction": "switch the view type to Cards on the Products grid",
      "assertions": [
        {
          "kind": "url",
          "urlPattern": "/app/data-explorer/Data"
        }
      ],
      "visualCriteria": [
        "The view-type switcher lists more than one type including 'Cards', and after selecting Cards the records re-render as a card grid instead of the tabular AG-Grid (or a valid empty-state for that view)"
      ]
    },
    {
      "name": "view-selector-select",
      "instruction": "open the saved-view selector and apply the (Default) view",
      "visualCriteria": [
        "Clicking the saved-view selector opens a Views panel listing at least a '(Default)' entry, and selecting a view applies it — a check indicator appears on the chosen view and the grid reloads (or a valid empty-state renders)"
      ]
    },
    {
      "name": "create-saved-view",
      "instruction": "create a new saved view via 'New View' and confirm it becomes active",
      "visualCriteria": [
        "A create/quick-save dialog with an editable view-name field appears after clicking 'New View', and after saving the newly named view becomes the selected view (name shown on the selector button) or appears under 'My Views'"
      ]
    },
    {
      "name": "timeline-view",
      "instruction": "switch the view type to Timeline (or an alternate type) and confirm re-render",
      "visualCriteria": [
        "The view-type switcher lists multiple types; if 'Timeline' is offered, selecting it renders a chronological timeline layout — otherwise an alternate type (e.g. Cards) is selectable and the view re-renders, or a valid empty-state shows"
      ]
    },
    {
      "name": "view-open-in-tab",
      "instruction": "open a saved view in its own tab via the Open-in-Tab action",
      "visualCriteria": [
        "With a saved view selected, the 'Open this view in a new tab' button (external-link icon beside the saved-view selector) opens that view as its own workspace tab showing the entity's records (or a valid empty-state), and the app stays responsive"
      ]
    },
    {
      "name": "reset-view",
      "instruction": "modify the view (sort/filter) then Reset to Default and confirm revert",
      "visualCriteria": [
        "After a sort or filter change the saved-view selector shows a modified indicator (unsaved-changes dot), and clicking 'Reset to Default' reverts the grid to the default view and the modified indicator clears"
      ]
    }
  ]
}
